129	async function printKitchenTicketsForItems(
130	  supabase: Awaited<ReturnType<typeof createClient>>,
131	  businessId: string,
132	  source: string,
133	  label: string,
134	  items: { productId: string; qty: number; note?: string | null }[],
135	) {
136	  const productIds = Array.from(new Set(items.map((i) => i.productId)));
137	  const { data: products } = await supabase
138	    .from("products")
139	    .select("id, name, category")
140	    .in("id", productIds);
141	  const productMap = new Map((products ?? []).map((p) => [p.id, p]));
142	
143	  const failures = await dispatchKitchenPrint(supabase, businessId, {
144	    source,
145	    label,
146	    items: items.map((i) => ({
147	      name: productMap.get(i.productId)?.name ?? "Item",
148	      category: productMap.get(i.productId)?.category ?? null,
149	      qty: i.qty,
150	      note: i.note,
151	    })),
152	  }).catch(() => []);
153	
154	  const failed = failures.filter((f) => !f.ok);
155	  if (failed.length > 0) {
156	    await logActivity(
157	      supabase,
158	      businessId,
159	      "sistem",
160	      "warning",
161	      `Gagal cetak ke dapur: ${failed.map((f) => f.printer).join(", ")}`,
162	      failed.map((f) => f.error).join(" · "),
163	    );
164	  }
165	}
