256	export async function saveOpenBill(
257	  businessId: string,
258	  billId: string | null,
259	  label: string,
260	  items: OpenBillItemInput[],
261	): Promise<SaveOpenBillResult> {
262	  const trimmed = label.trim();
263	  if (!trimmed) {
264	    return { success: false, error: "Nama bon wajib diisi." };
265	  }
266	  if (items.length === 0) {
267	    return { success: false, error: "Keranjang masih kosong." };
268	  }
269	
270	  const supabase = await createClient();
271	
272	  if (billId) {
273	    const { error } = await supabase
274	      .from("open_bills")
275	      .update({ label: trimmed, items, updated_at: new Date().toISOString() })
276	      .eq("id", billId)
277	      .eq("business_id", businessId);
278	    if (error) {
279	      return { success: false, error: error.message };
280	    }
281	    revalidatePath(`/business/${businessId}/pos`);
282	    return { success: true, billId };
283	  }
284	
285	  const { data, error } = await supabase
286	    .from("open_bills")
287	    .insert({ business_id: businessId, label: trimmed, items })
288	    .select("id")
289	    .single();
290	
291	  if (error || !data) {
292	    return { success: false, error: error?.message ?? "Gagal menyimpan bon." };
293	  }
294	
295	  await logActivity(
296	    supabase,
297	    businessId,
298	    "transaksi",
299	    "info",
300	    `Open Bill dibuat: ${trimmed}`,
301	    `${items.length} jenis item`,
302	  );
303	  revalidatePath(`/business/${businessId}/pos`);
304	  return { success: true, billId: data.id };
305	}
