307	export async function deleteOpenBill(businessId: string, billId: string) {
308	  const supabase = await createClient();
309	  await supabase.from("open_bills").delete().eq("id", billId).eq("business_id", businessId);
310	  revalidatePath(`/business/${businessId}/pos`);
311	}
