313	export async function updateSelfOrderStatus(
314	  businessId: string,
315	  orderId: string,
316	  status: "diproses" | "selesai",
317	): Promise<{ success: boolean; error?: string }> {
318	  const supabase = await createClient();
319	  const { data, error } = await supabase
320	    .from("self_orders")
321	    .update({ status })
322	    .eq("id", orderId)
323	    .eq("business_id", businessId)
324	    .select("tables(name)")
325	    .single();
326	
327	  if (error) {
328	    return { success: false, error: error.message };
329	  }
330	
331	  const tableName =
332	    (data as unknown as { tables: { name: string } | null }).tables?.name ?? "Meja terhapus";
333	  await logActivity(
334	    supabase,
335	    businessId,
336	    "transaksi",
337	    "info",
338	    `Pesanan ${tableName} → ${status}`,
339	  );
340	
341	  if (status === "diproses") {
342	    const { data: orderItems } = await supabase
343	      .from("self_order_items")
344	      .select("product_id, name, qty, note, products(category)")
345	      .eq("self_order_id", orderId);
346	
347	    if (orderItems && orderItems.length > 0) {
348	      const failures = await dispatchKitchenPrint(supabase, businessId, {
349	        source: tableName,
350	        label: "Pesanan Self-Order",
351	        items: orderItems.map((i) => ({
352	          name: i.name,
353	          category: (i as unknown as { products: { category: string | null } | null }).products
354	            ?.category ?? null,
355	          qty: Number(i.qty),
356	          note: i.note,
357	        })),
358	      }).catch(() => []);
359	
360	      const failed = failures.filter((f) => !f.ok);
361	      if (failed.length > 0) {
362	        await logActivity(
363	          supabase,
364	          businessId,
365	          "sistem",
366	          "warning",
367	          `Gagal cetak ke dapur: ${failed.map((f) => f.printer).join(", ")}`,
368	          failed.map((f) => f.error).join(" · "),
369	        );
370	      }
371	    }
372	  }
373	
374	  revalidatePath(`/business/${businessId}/pos`);
375	  revalidatePath(`/business/${businessId}/tables`);
376	  return { success: true };
377	}
