30	// angka final secara independen; ini dipakai untuk tampilan kasir.
31	export function calculateCheckoutTotals(params: {
32	  items: CheckoutLineItem[];
33	  orderDisc: number;
34	  orderDiscType: DiscountType;
35	  serviceRate: number;
36	  taxRate: number;
